import hashlib
import hmac
import os
import time
import json
import re
import secrets
from typing import Optional, Dict, Any, Tuple

# Session-based file access control system
# Supports role-based access with cryptographic session tokens

SESSION_SECRET = os.environ.get('SESSION_SECRET', secrets.token_hex(32))
UPLOAD_DIR = '/var/app/uploads'
SHARED_DIR = '/var/app/shared'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.csv'}

class AccessPolicy:
    """Defines access control policies for file operations."""

    ROLE_PERMISSIONS = {
        'admin': {'read', 'write', 'delete', 'list', 'share'},
        'editor': {'read', 'write', 'list', 'share'},
        'viewer': {'read', 'list'},
        'guest': {'list'},
    }

    # Path access matrix: role -> allowed path prefixes
    PATH_ACCESS = {
        'admin': [UPLOAD_DIR, SHARED_DIR, '/var/app/config'],
        'editor': [UPLOAD_DIR, SHARED_DIR],
        'viewer': [SHARED_DIR],
        'guest': [SHARED_DIR + '/public'],
    }

    @staticmethod
    def check_permission(role: str, action: str) -> bool:
        """Check if role has permission for the given action."""
        perms = AccessPolicy.ROLE_PERMISSIONS.get(role, set())
        return action in perms

    @staticmethod
    def check_path_access(role: str, resolved_path: str) -> bool:
        """Check if role can access the resolved filesystem path."""
        allowed_prefixes = AccessPolicy.PATH_ACCESS.get(role, [])
        for prefix in allowed_prefixes:
            if resolved_path.startswith(prefix):
                return True
        return False


class SessionManager:
    """Manages cryptographic session tokens with HMAC integrity."""

    def __init__(self, secret: str):
        self._secret = secret.encode('utf-8')
        self._revoked: set = set()

    def create_session(self, user_id: str, role: str, 
                       duration: int = 3600) -> str:
        """Create a signed session token."""
        payload = {
            'uid': user_id,
            'role': role,
            'iat': int(time.time()),
            'exp': int(time.time()) + duration,
            'jti': secrets.token_hex(16),
        }
        payload_bytes = json.dumps(payload, separators=(',', ':')).encode()
        mac = hmac.new(self._secret, payload_bytes, hashlib.sha256).hexdigest()
        import base64
        token = base64.urlsafe_b64encode(payload_bytes).decode() + '.' + mac
        return token

    def validate_session(self, token: str) -> Optional[Dict[str, Any]]:
        """Validate session token integrity and expiration."""
        import base64
        try:
            parts = token.split('.', 1)
            if len(parts) != 2:
                return None
            payload_b64, provided_mac = parts
            payload_bytes = base64.urlsafe_b64decode(payload_b64 + '==')
            expected_mac = hmac.new(
                self._secret, payload_bytes, hashlib.sha256
            ).hexdigest()
            if not hmac.compare_digest(expected_mac, provided_mac):
                return None
            payload = json.loads(payload_bytes)
            if payload.get('jti') in self._revoked:
                return None
            now = int(time.time())
            if now > payload.get('exp', 0):
                return None
            if now < payload.get('iat', now) - 60:
                return None
            return payload
        except Exception:
            return None

    def revoke_session(self, jti: str):
        self._revoked.add(jti)


def sanitize_filename(filename: str) -> Optional[str]:
    """Sanitize a filename, rejecting path traversal attempts."""
    # Strip any null bytes
    if '\x00' in filename:
        return None
    # Reject any path separators
    if '/' in filename or '\\' in filename:
        return None
    # Reject hidden files
    if filename.startswith('.'):
        return None
    # Reject path traversal sequences
    if '..' in filename:
        return None
    # Validate extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None
    # Validate characters (alphanumeric, dash, underscore, dot, space)
    if not re.match(r'^[a-zA-Z0-9_\-. ]+$', filename):
        return None
    return filename


def resolve_file_path(base_dir: str, filename: str) -> Optional[str]:
    """Safely resolve a file path within the given base directory."""
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        return None
    # Construct full path and resolve symlinks
    full_path = os.path.realpath(os.path.join(base_dir, clean_name))
    # Verify the resolved path is within the base directory
    real_base = os.path.realpath(base_dir)
    if not full_path.startswith(real_base + os.sep) and full_path != real_base:
        return None
    return full_path


def handle_file_request(session_mgr: SessionManager, 
                        token: str, 
                        action: str,
                        directory: str,
                        filename: str,
                        content: Optional[bytes] = None) -> Tuple[int, str]:
    """Process a file access request with full auth chain."""

    # Step 1: Validate session
    session = session_mgr.validate_session(token)
    if session is None:
        return (401, 'Invalid or expired session')

    user_id = session.get('uid', '')
    role = session.get('role', '')

    # Step 2: Validate action format
    if action not in ('read', 'write', 'delete', 'list', 'share'):
        return (400, 'Invalid action')

    # Step 3: Check role permission for action
    if not AccessPolicy.check_permission(role, action):
        return (403, f'Role {role} cannot perform {action}')

    # Step 4: Resolve and validate file path
    resolved = resolve_file_path(directory, filename)
    if resolved is None:
        return (400, 'Invalid filename or path')

    # Step 5: Check path-level access control
    # NOTE: We check if the user's role grants access to the TARGET path
    if not AccessPolicy.check_path_access(role, resolved):
        return (403, 'Access denied to this path')

    # Step 6: For share action, verify source is accessible AND
    # destination (shared dir) is writable by the role
    if action == 'share':
        # Share copies file to shared directory
        share_dest = resolve_file_path(SHARED_DIR, filename)
        if share_dest is None:
            return (400, 'Cannot share: invalid filename')
        # Verify role can write to shared dir
        if not AccessPolicy.check_path_access(role, share_dest):
            return (403, 'Cannot share: no access to shared directory')

    # Step 7: Execute action
    try:
        if action == 'read':
            if not os.path.isfile(resolved):
                return (404, 'File not found')
            with open(resolved, 'rb') as f:
                data = f.read(10 * 1024 * 1024)  # 10MB limit
            return (200, f'Read {len(data)} bytes')

        elif action == 'write':
            if content is None:
                return (400, 'No content provided')
            if len(content) > 10 * 1024 * 1024:
                return (413, 'Content too large')
            os.makedirs(os.path.dirname(resolved), exist_ok=True)
            with open(resolved, 'wb') as f:
                f.write(content)
            return (201, 'File written')

        elif action == 'delete':
            if not os.path.isfile(resolved):
                return (404, 'File not found')
            os.remove(resolved)
            return (200, 'File deleted')

        elif action == 'list':
            target = resolved if os.path.isdir(resolved) else os.path.dirname(resolved)
            if os.path.isdir(target):
                entries = os.listdir(target)
                return (200, json.dumps(entries[:100]))
            return (404, 'Directory not found')

        elif action == 'share':
            if not os.path.isfile(resolved):
                return (404, 'Source file not found')
            import shutil
            share_dest = resolve_file_path(SHARED_DIR, filename)
            shutil.copy2(resolved, share_dest)
            return (200, 'File shared')

    except PermissionError:
        return (403, 'OS permission denied')
    except OSError as e:
        return (500, f'IO error: {e}')

    return (500, 'Unexpected state')


def handle_admin_override(session_mgr: SessionManager,
                          token: str,
                          target_path: str,
                          action: str,
                          content: Optional[bytes] = None) -> Tuple[int, str]:
    """Admin-only direct path access (bypasses filename sanitization).
    Used for system maintenance operations."""

    session = session_mgr.validate_session(token)
    if session is None:
        return (401, 'Invalid or expired session')

    role = session.get('role', '')

    # Only admins can use direct path access
    if role != 'admin':
        return (403, 'Admin only')

    # Resolve the path to prevent symlink attacks
    resolved = os.path.realpath(target_path)

    # Even admins are restricted to app directories
    app_root = os.path.realpath('/var/app')
    if not resolved.startswith(app_root + os.sep):
        return (403, 'Path outside application root')

    if not AccessPolicy.check_permission(role, action):
        return (403, 'Permission denied')

    try:
        if action == 'read':
            with open(resolved, 'rb') as f:
                return (200, f.read(10*1024*1024).decode('utf-8', errors='replace'))
        elif action == 'write':
            if content:
                with open(resolved, 'wb') as f:
                    f.write(content)
                return (200, 'Written')
        elif action == 'delete':
            os.remove(resolved)
            return (200, 'Deleted')
    except OSError as e:
        return (500, str(e))

    return (400, 'Invalid')


# HTTP request handler (simplified WSGI-like interface)
def application(environ: Dict[str, Any]) -> Tuple[int, str]:
    """Main request dispatcher."""
    session_mgr = SessionManager(SESSION_SECRET)

    method = environ.get('REQUEST_METHOD', 'GET')
    path = environ.get('PATH_INFO', '/')
    headers = environ.get('headers', {})
    body = environ.get('body', b'')

    token = headers.get('Authorization', '').replace('Bearer ', '')

    if path.startswith('/api/files/'):
        # Parse: /api/files/{action}/{directory_b64}/{filename}
        parts = path[len('/api/files/'):].split('/', 2)
        if len(parts) != 3:
            return (400, 'Invalid path format')

        action = parts[0]
        import base64
        try:
            directory = base64.urlsafe_b64decode(parts[1] + '==').decode()
        except Exception:
            return (400, 'Invalid directory encoding')
        filename = parts[2]

        return handle_file_request(
            session_mgr, token, action, directory, filename,
            content=body if method == 'POST' else None
        )

    elif path.startswith('/api/admin/'):
        # Parse: /api/admin/{action}?path=...
        action = path[len('/api/admin/'):]
        target = environ.get('QUERY_STRING', '').split('path=', 1)
        if len(target) < 2:
            return (400, 'Missing path parameter')
        import urllib.parse
        target_path = urllib.parse.unquote(target[1])

        return handle_admin_override(
            session_mgr, token, target_path, action,
            content=body if method in ('POST', 'PUT') else None
        )

    return (404, 'Not found')
